"""Inheritance flags for the objects the host hands to its helpers."""

import os

from .errors import WSpawnError
from . import _winapi


def _as_number(handle):
    try:
        return int(handle)
    except (TypeError, ValueError):
        raise WSpawnError("handle must be an integer, got %r" % (handle,), kind="badarg")


def set_inheritable(handle, enabled=True):
    """Mark ``handle`` as transferable to child processes, or stop it being so.

    Uses the Win32 ``SetHandleInformation`` API so that the change is visible
    at the handle level (not just the C-runtime file-descriptor level).
    """
    number = _as_number(handle)
    if not _winapi.is_windows():
        raise WSpawnError(
            "set_inheritable requires Windows",
            kind="unsupported",
            handle=handle,
        )
    try:
        mask = _winapi.HANDLE_FLAG_INHERIT
        flags = _winapi.HANDLE_FLAG_INHERIT if enabled else 0
        _winapi.set_handle_information(number, mask, flags)
    except OSError as exc:
        # ERROR_INVALID_HANDLE (6) means the handle doesn't exist or isn't a
        # real kernel object.  That's an "unsupported" situation rather than a
        # generic OS failure because no amount of retrying will help.
        winerr = exc.args[0] if exc.args else 0
        if winerr == 6:  # ERROR_INVALID_HANDLE
            raise WSpawnError(
                "handle %r does not support inheritance control" % (handle,),
                kind="unsupported",
                handle=handle,
            ) from exc
        raise WSpawnError(str(exc), kind="os", handle=handle) from exc


def is_inheritable(handle):
    """Return ``True`` when ``handle`` is currently transferable.

    Reads the flag via ``GetHandleInformation`` so the result matches what the
    operating system actually sees.
    """
    number = _as_number(handle)
    if not _winapi.is_windows():
        raise WSpawnError(
            "is_inheritable requires Windows",
            kind="unsupported",
            handle=handle,
        )
    try:
        flags = _winapi.get_handle_information(number)
        return bool(flags & _winapi.HANDLE_FLAG_INHERIT)
    except OSError as exc:
        winerr = exc.args[0] if exc.args else 0
        if winerr == 6:  # ERROR_INVALID_HANDLE
            raise WSpawnError(
                "handle %r does not support inheritance queries" % (handle,),
                kind="unsupported",
                handle=handle,
            ) from exc
        raise WSpawnError(str(exc), kind="os", handle=handle) from exc


def inheritable_handles():
    """Return every object in this process that is currently transferable.

    Enumerates all open handles via ``NtQuerySystemInformation`` and filters
    those with ``HANDLE_FLAG_INHERIT`` set.
    """
    if not _winapi.is_windows():
        return []
    try:
        all_handles = _winapi.enumerate_handles()
    except OSError:
        return []
    result = []
    for h in all_handles:
        try:
            flags = _winapi.get_handle_information(h)
            if flags & _winapi.HANDLE_FLAG_INHERIT:
                result.append(h)
        except OSError:
            continue
    return tuple(result)

"""Classification of the objects the host may hand to its helpers."""

from .errors import WSpawnError
from . import _winapi


def handle_kind(handle):
    """Return ``"file"``, ``"pipe"``, ``"console"`` or ``"unknown"``.

    Uses the Win32 ``GetFileType`` API to distinguish object types.  Raises
    :class:`WSpawnError` for invalid handles or non-integer arguments.
    """
    try:
        number = int(handle)
    except (TypeError, ValueError):
        raise WSpawnError("handle must be an integer, got %r" % (handle,), kind="badarg")

    if not _winapi.is_windows():
        raise WSpawnError(
            "handle_kind requires Windows",
            kind="unsupported",
            handle=handle,
        )

    # Validate that the handle is actually valid by checking GetHandleInformation
    try:
        _winapi.get_handle_information(number)
    except OSError as exc:
        winerr = exc.args[0] if exc.args else 0
        if winerr == 6:  # ERROR_INVALID_HANDLE
            raise WSpawnError(
                "not a valid handle: %r" % (handle,),
                kind="badarg",
                handle=handle,
            ) from exc
        raise WSpawnError(str(exc), kind="os", handle=handle) from exc

    ft = _winapi.file_type(number)
    if ft == _winapi.FILE_TYPE_DISK:
        return "file"
    elif ft == _winapi.FILE_TYPE_PIPE:
        return "pipe"
    elif ft == _winapi.FILE_TYPE_CHAR:
        return "console"
    else:
        return "unknown"
